"use client";

import type { ComponentProps } from "react";
import { useEffect } from "react";
import { cn } from "@/components/control-ui/lib/cn";
import { type ControlEffect, controlEffectsAttribute } from "@/components/control-ui/skin";
import { useSkin } from "@/components/control-ui/skin-provider";

export type ControlEffectsRootProps = ComponentProps<"div"> & {
  effects?: readonly ControlEffect[];
};

const EMPTY_EFFECTS: readonly ControlEffect[] = [];
const controlSelector = '[data-control-ui][data-control="true"]';
const rippleAnimationName = "cui-ripple-pulse";

function onRippleEnd(event: AnimationEvent) {
  // a nested control's pulse bubbles through its ancestors; only the control that owns the pulse settles here
  if (event.animationName !== rippleAnimationName || event.target !== event.currentTarget) return;
  const control = event.currentTarget;
  if (!(control instanceof HTMLElement)) return;
  // a retrigger cancels the previous pulse, and that late animationcancel must not clear the pulse that replaced it
  if (
    event.type === "animationcancel" &&
    control.getAnimations().some((animation) => animation instanceof CSSAnimation && animation.animationName === rippleAnimationName)
  ) {
    return;
  }
  control.removeAttribute("data-ripple");
  control.removeEventListener("animationend", onRippleEnd);
  control.removeEventListener("animationcancel", onRippleEnd);
}

function startRipple(control: HTMLElement, event: PointerEvent) {
  if (event.pointerType === "mouse" && event.button !== 0) return;
  if (control.matches(":disabled,[aria-disabled='true'],[data-disabled]")) return;

  const rect = control.getBoundingClientRect();
  control.style.setProperty("--aui-ripple-x", `${event.clientX - rect.left}px`);
  control.style.setProperty("--aui-ripple-y", `${event.clientY - rect.top}px`);

  control.style.setProperty("--aui-ripple-r", `${Math.ceil(Math.max(rect.width, rect.height) * 1.1)}px`);

  control.removeAttribute("data-ripple");
  void control.offsetWidth;
  control.setAttribute("data-ripple", "");
  control.addEventListener("animationend", onRippleEnd);
  // a control hidden mid-pulse (closing popup, collapsing panel) never fires animationend; without this the attribute stays and the pulse replays when the control is shown again
  control.addEventListener("animationcancel", onRippleEnd);
}

let rippleClients = 0;

function onDocumentPointerDown(event: PointerEvent) {
  if (event.defaultPrevented || !(event.target instanceof Element)) return;
  const control = event.target.closest<HTMLElement>(controlSelector);
  if (!control?.closest('[data-effects~="ripple"]')) return;
  startRipple(control, event);
}

function acquireRippleListener() {
  if (rippleClients === 0) document.addEventListener("pointerdown", onDocumentPointerDown);
  rippleClients += 1;
  return () => {
    rippleClients -= 1;
    if (rippleClients === 0) document.removeEventListener("pointerdown", onDocumentPointerDown);
  };
}

let hoverCircleClients = 0;
let hoverCircleControl: HTMLElement | null = null;
let hoverCircleRect: DOMRect | null = null;

function onDocumentPointerMove(event: PointerEvent) {
  if (!(event.target instanceof Element)) return;
  const control = event.target.closest<HTMLElement>(controlSelector);
  if (control !== hoverCircleControl) {
    hoverCircleControl = control?.closest('[data-effects~="hover-circle"]') ? control : null;
    hoverCircleRect = null;
  }
  if (!hoverCircleControl) return;
  if (!hoverCircleRect) {
    hoverCircleRect = hoverCircleControl.getBoundingClientRect();
    const radius = Math.ceil(Math.max(hoverCircleRect.width, hoverCircleRect.height) * 1.1);
    hoverCircleControl.style.setProperty("--aui-hover-circle-r", `${radius}px`);
  }
  hoverCircleControl.style.setProperty("--aui-hover-circle-x", `${event.clientX - hoverCircleRect.left}px`);
  hoverCircleControl.style.setProperty("--aui-hover-circle-y", `${event.clientY - hoverCircleRect.top}px`);
}

// the rect is cached per hovered control; any scroll moves the control under the pointer, so the next move re-measures
function onDocumentScroll() {
  hoverCircleRect = null;
}

function acquireHoverCircleListener() {
  if (hoverCircleClients === 0) {
    document.addEventListener("pointermove", onDocumentPointerMove, { passive: true });
    document.addEventListener("scroll", onDocumentScroll, { capture: true, passive: true });
  }
  hoverCircleClients += 1;
  return () => {
    hoverCircleClients -= 1;
    if (hoverCircleClients === 0) {
      document.removeEventListener("pointermove", onDocumentPointerMove);
      document.removeEventListener("scroll", onDocumentScroll, { capture: true });
      hoverCircleControl = null;
      hoverCircleRect = null;
    }
  };
}

export function ControlEffectsRoot({ effects = EMPTY_EFFECTS, className, children, ...props }: ControlEffectsRootProps) {
  const effectsValue = controlEffectsAttribute(effects);
  const hasRipple = effects.includes("ripple");
  const hasHoverCircle = effects.includes("hover-circle");

  useEffect(() => (hasRipple ? acquireRippleListener() : undefined), [hasRipple]);
  useEffect(() => (hasHoverCircle ? acquireHoverCircleListener() : undefined), [hasHoverCircle]);

  return (
    <div data-effects={effectsValue} className={cn("contents", className)} {...props}>
      {children}
    </div>
  );
}

export function ControlEffectsRuntime() {
  const skin = useSkin();
  const effectsValue = controlEffectsAttribute(skin.effects);

  useEffect(() => {
    const html = document.documentElement;
    if (effectsValue === undefined) html.removeAttribute("data-effects");
    else html.setAttribute("data-effects", effectsValue);
    return () => html.removeAttribute("data-effects");
  }, [effectsValue]);

  useEffect(() => acquireRippleListener(), []);

  useEffect(() => (effectsValue?.includes("hover-circle") ? acquireHoverCircleListener() : undefined), [effectsValue]);

  return null;
}

/* Control effects: data-driven + CSS-first. Primitives emit stable anatomy plus data-control; a skin or extension root opts in via data-effects="top-shine ripple".
 * No effect injects DOM: top-shine on ::before, ripple on control's own background-image (clipped by border-radius, composes with both).
 * ControlEffectsRoot only feeds click geometry via --aui-ripple-* + retriggers keyframes — streaming DOM updates cost nothing (no observer, nothing to re-sync). */
/* Lowest author layer: a recipe or utility that already positions or clips a control (absolute modal close button,
 * overflow-hidden number field) keeps its own value; only unpositioned controls gain a containing block here. */
@layer base {
  [data-effects~="top-shine"] :where([data-control-ui][data-control="true"]),
  [data-effects~="ripple"] :where([data-control-ui][data-control="true"]),
  [data-effects~="hover-circle"] :where([data-control-ui][data-control="true"]) {
    position: relative;
    isolation: isolate;
  }
}

[data-effects~="top-shine"] :where([data-control-ui][data-control="true"])::before {
  content: "";
  pointer-events: none;
  position: absolute;
  z-index: 2;
  inset-inline: 0.5rem;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, oklch(from var(--foreground) l c h / 0.32), transparent);
  opacity: 0;
  transition: opacity var(--duration-fast) var(--ease-standard);
}

[data-effects~="top-shine"] :where([data-control-ui][data-control="true"]:focus-visible)::before {
  opacity: 1;
}

@media (hover: hover) {
  [data-effects~="top-shine"]
    :where([data-control-ui][data-control="true"]:hover:not(:disabled, [data-disabled], [aria-disabled="true"]))::before {
    opacity: 1;
  }
}

/* ripple — click feedback via control's own background-image; ControlEffectsRoot sets --aui-ripple-x/y/r from pointer + toggles data-ripple, keyframes animate the two registered properties the radial-gradient reads.
 * Registration required for interpolation — browsers without @property degrade to a brief static flash, never broken layout. */
@property --cui-ripple-scale {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}

@property --cui-ripple-alpha {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}

[data-effects~="ripple"] :where([data-control-ui][data-control="true"][data-ripple]) {
  background-image: radial-gradient(
    circle calc(var(--aui-ripple-r, 0px) * var(--cui-ripple-scale)) at var(--aui-ripple-x, 50%) var(--aui-ripple-y, 50%),
    oklch(from var(--foreground) l c h / calc(0.24 * var(--cui-ripple-alpha))) 0%,
    oklch(from var(--foreground) l c h / calc(0.14 * var(--cui-ripple-alpha))) 42%,
    transparent 70%
  );
  animation: cui-ripple-pulse calc(var(--duration-slow) * 2.2) var(--ease-emphasized) forwards;
}

@keyframes cui-ripple-pulse {
  0% {
    --cui-ripple-scale: 0;
    --cui-ripple-alpha: 0.45;
  }
  70% {
    --cui-ripple-alpha: 0.18;
  }
  100% {
    --cui-ripple-scale: 1;
    --cui-ripple-alpha: 0;
  }
}

/* hover-circle — pointer-following blend disc: grows from the cursor on enter, tracks it across the
 * control, recedes on leave; mix-blend-mode:difference inverts whatever it crosses (text included).
 * ControlEffectsRoot only streams --aui-hover-circle-x/y/r (CSS can't observe pointer coords); the
 * grow/shrink is a registered-property transition on :hover, everything else stays declarative.
 * The disc is the ::after's own background — clipped by border-radius:inherit, no injected DOM.
 * Tokens: --aui-hover-circle-color (disc paint), radius fed per-control by the runtime.
 * Registration required for interpolation — without @property the disc still appears/disappears, it just skips the growth. */
@property --cui-hover-circle-scale {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}

/* Hover-capable pointers only: on touch, :hover sticks after tap and the disc would freeze mid-control. */
@media (hover: hover) {
  [data-effects~="hover-circle"] :where([data-control-ui][data-control="true"])::after {
    content: "";
    pointer-events: none;
    position: absolute;
    z-index: 2;
    inset: 0;
    /* Buttons, toolbar items, and pagination links already own ::after as a centred, min-sized hit target; without these resets the disc layer inherits that box and sits half a control up and to the left. */
    translate: none;
    inline-size: auto;
    block-size: auto;
    border-radius: inherit;
    corner-shape: inherit;
    background-image: radial-gradient(
      circle calc(var(--aui-hover-circle-r, 6rem) * var(--cui-hover-circle-scale)) at var(--aui-hover-circle-x, 50%)
        var(--aui-hover-circle-y, 50%),
      var(--aui-hover-circle-color, oklch(1 0 0 / 0.24)) calc(100% - 1px),
      transparent 100%
    );
    mix-blend-mode: difference;
    transition: --cui-hover-circle-scale calc(var(--duration-slow) * 1.6) var(--ease-emphasized);
  }

  /* Same disabled guard as the ripple's JS check and the recipes: Base UI stamps a bare data-disabled, so presence is the test. */
  [data-effects~="hover-circle"]
  :where([data-control-ui][data-control="true"]:hover:not(:disabled, [aria-disabled="true"], [data-disabled]))::after {
    --cui-hover-circle-scale: 1;
  }
}
